    q("dx_001","Resumen ejecutivo global","Cual es el resumen ejecutivo de todos los KPIs del negocio?","Combina facturacion, SATs, presupuestos, albaranes, pedidos, clientes, articulos.","SELECT (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=13) AS N_FACTURAS, ROUND((SELECT SUM(IMPORTETOTAL) FROM DOCCAB WHERE TIPO=13),2) AS FACTURACION_TOTAL, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=2) AS N_SATS, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=0) AS N_PRESUPUESTOS, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=11) AS N_ALBARANES, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=12) AS N_PEDIDOS_PROVEEDOR, (SELECT COUNT(*) FROM CLIENTE WHERE BAJA IS NULL OR BAJA!=1) AS N_CLIENTES, (SELECT COUNT(*) FROM ARTICULO WHERE BAJA IS NULL OR BAJA!=1) AS N_ARTICULOS","NULL","Director","KPI","Critico","Resumen ejecutivo global",""),
    q("dx_002","Resumen ejecutivo del mes actual","Cual es el resumen ejecutivo del mes actual?","Combina facturacion, SATs, presupuestos del mes actual.","SELECT ROUND((SELECT SUM(IMPORTETOTAL) FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')),2) AS FACTURACION_MES, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')) AS N_FACTURAS_MES, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')) AS N_SATS_MES, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=0 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')) AS N_PRESUPUESTOS_MES","NULL","Director","KPI","Critico","Resumen mes",""),
    q("dx_003","Resumen ejecutivo del anio actual","Cual es el resumen ejecutivo del anio actual?","Combina facturacion, SATs, presupuestos del anio actual.","SELECT ROUND((SELECT SUM(IMPORTETOTAL) FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,4)=strftime('%Y','now')),2) AS FACTURACION_ANIO, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,4)=strftime('%Y','now')) AS N_FACTURAS_ANIO, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,4)=strftime('%Y','now')) AS N_SATS_ANIO, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=0 AND SUBSTR(FECHA,1,4)=strftime('%Y','now')) AS N_PRESUPUESTOS_ANIO","NULL","Director","KPI","Critico","Resumen anio",""),
    q("dx_004","Evolucion de todos los tipos de documento por mes","Como evoluciona el volumen de cada tipo de documento mes a mes?","COUNT de DOCCAB por TIPO y mes.","SELECT SUBSTR(FECHA,1,7) AS MES, TIPO, COUNT(*) AS N_DOCS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,7), TIPO ORDER BY MES DESC, TIPO ASC LIMIT 60","NULL","Director","Estrategico","Alto","",""),
    q("dx_005","Evolucion de todos los tipos de documento por anio","Como evoluciona el volumen de cada tipo de documento anio a anio?","COUNT de DOCCAB por TIPO y anio.","SELECT SUBSTR(FECHA,1,4) AS ANIO, TIPO, COUNT(*) AS N_DOCS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), TIPO ORDER BY ANIO DESC, TIPO ASC LIMIT 30","NULL","Director","Estrategico","Alto","",""),
    q("dx_006","Ratio conversion presupuesto a factura","Que porcentaje de presupuestos se convierten en facturas?","Clientes con TIPO=0 y TIPO=13 en DOCCAB.","SELECT (SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=0) AS CLIENTES_CON_PRESUPUESTO, (SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=13) AS CLIENTES_CON_FACTURA, (SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=0 AND CODCLIENTE IN (SELECT DISTINCT CODCLIENTE FROM DOCCAB WHERE TIPO=13)) AS CLIENTES_CONVERTIDOS, ROUND(100.0*(SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=0 AND CODCLIENTE IN (SELECT DISTINCT CODCLIENTE FROM DOCCAB WHERE TIPO=13))/(SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=0),1) AS PCT_CONVERSION","NULL","Director","KPI","Critico","Conversion presupuesto",""),
    q("dx_007","Ratio conversion presupuesto a factura por mes","Como evoluciona la conversion de presupuestos a facturas mes a mes?","Clientes con TIPO=0 y TIPO=13 en DOCCAB por mes.","SELECT SUBSTR(FECHA,1,7) AS MES, SUM(CASE WHEN TIPO=0 THEN 1 ELSE 0 END) AS N_PRESUPUESTOS, SUM(CASE WHEN TIPO=13 THEN 1 ELSE 0 END) AS N_FACTURAS, ROUND(100.0*SUM(CASE WHEN TIPO=13 THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN TIPO=0 THEN 1 ELSE 0 END),0),1) AS RATIO_CONVERSION FROM DOCCAB WHERE TIPO IN (0,13) AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,7) ORDER BY MES DESC LIMIT 24","NULL","Director","KPI","Alto","",""),
    q("dx_008","Ratio conversion presupuesto a factura por agente","Que agentes convierten mas presupuestos en facturas?","Clientes con TIPO=0 y TIPO=13 en DOCCAB por agente.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, SUM(CASE WHEN TIPO=0 THEN 1 ELSE 0 END) AS N_PRESUPUESTOS, SUM(CASE WHEN TIPO=13 THEN 1 ELSE 0 END) AS N_FACTURAS, ROUND(100.0*SUM(CASE WHEN TIPO=13 THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN TIPO=0 THEN 1 ELSE 0 END),0),1) AS RATIO_CONVERSION FROM DOCCAB WHERE TIPO IN (0,13) AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY RATIO_CONVERSION DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_009","Clientes nuevos por mes","Cuantos clientes nuevos se han dado de alta cada mes?","COUNT de CLIENTE por mes de alta.","SELECT SUBSTR(FECHAALTA,1,7) AS MES, COUNT(*) AS N_CLIENTES_NUEVOS FROM CLIENTE WHERE FECHAALTA IS NOT NULL GROUP BY SUBSTR(FECHAALTA,1,7) ORDER BY MES DESC LIMIT 24","NULL","Director","KPI","Alto","Clientes nuevos",""),
