    q("dx_011","Clientes activos en el mes actual","Cuantos clientes han tenido actividad este mes?","COUNT de DOCCAB TIPO=13 del mes actual con clientes distintos.","SELECT COUNT(DISTINCT CODCLIENTE) AS N_CLIENTES_ACTIVOS FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')","NULL","Director","KPI","Critico","Clientes activos mes",""),
    q("dx_012","Clientes activos en el anio actual","Cuantos clientes han tenido actividad este anio?","COUNT de DOCCAB TIPO=13 del anio actual con clientes distintos.","SELECT COUNT(DISTINCT CODCLIENTE) AS N_CLIENTES_ACTIVOS FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,4)=strftime('%Y','now')","NULL","Director","KPI","Critico","Clientes activos anio",""),
    q("dx_013","Clientes activos en el trimestre actual","Cuantos clientes han tenido actividad en los ultimos 3 meses?","COUNT de DOCCAB TIPO=13 con FECHA>=date('now','-90 days') con clientes distintos.","SELECT COUNT(DISTINCT CODCLIENTE) AS N_CLIENTES_ACTIVOS FROM DOCCAB WHERE TIPO=13 AND FECHA>=date('now','-90 days')","NULL","Director","KPI","Alto","",""),
