    q("dx_017","Clientes con primera compra en el mes actual","Cuantos clientes han comprado por primera vez este mes?","Clientes cuya primera factura es del mes actual.","SELECT COUNT(*) AS N_CLIENTES_PRIMERA_COMPRA FROM (SELECT CODCLIENTE, MIN(FECHA) AS PRIMERA_COMPRA FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL GROUP BY CODCLIENTE) WHERE SUBSTR(PRIMERA_COMPRA,1,7)=strftime('%Y-%m','now')","NULL","Director","KPI","Alto","Nuevos compradores",""),
    q("dx_018","Clientes con primera compra en el anio actual","Cuantos clientes han comprado por primera vez este anio?","Clientes cuya primera factura es del anio actual.","SELECT COUNT(*) AS N_CLIENTES_PRIMERA_COMPRA FROM (SELECT CODCLIENTE, MIN(FECHA) AS PRIMERA_COMPRA FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL GROUP BY CODCLIENTE) WHERE SUBSTR(PRIMERA_COMPRA,1,4)=strftime('%Y','now')","NULL","Director","KPI","Alto","",""),
    q("dx_019","Clientes con primera compra en el trimestre actual","Cuantos clientes han comprado por primera vez en los ultimos 3 meses?","Clientes cuya primera factura es de los ultimos 90 dias.","SELECT COUNT(*) AS N_CLIENTES_PRIMERA_COMPRA FROM (SELECT CODCLIENTE, MIN(FECHA) AS PRIMERA_COMPRA FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL GROUP BY CODCLIENTE) WHERE PRIMERA_COMPRA>=date('now','-90 days')","NULL","Director","KPI","Alto","",""),
    q("dx_020","Clientes con mas de una compra en el mes actual","Cuantos clientes han comprado mas de una vez este mes?","Clientes con mas de 1 factura en DOCCAB TIPO=13 del mes actual.","SELECT COUNT(*) AS N_CLIENTES_RECURRENTES FROM (SELECT CODCLIENTE, COUNT(*) AS N_FACTURAS FROM DOCCAB WHERE TIPO=13 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') AND CODCLIENTE IS NOT NULL GROUP BY CODCLIENTE HAVING COUNT(*)>1)","NULL","Director","KPI","Alto","Clientes recurrentes",""),
