    q("dx_025","Clientes con mas de 20 compras en toda la historia","Cuantos clientes han comprado mas de 20 veces en toda la historia?","Clientes con mas de 20 facturas en DOCCAB TIPO=13 (sin filtro).","SELECT COUNT(*) AS N_CLIENTES_FIELES FROM (SELECT CODCLIENTE, COUNT(*) AS N_FACTURAS FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL GROUP BY CODCLIENTE HAVING COUNT(*)>20)","NULL","Director","KPI","Alto","Clientes fieles",""),
    q("dx_026","Clientes con mayor frecuencia de compra","Cuales son los clientes que compran con mas frecuencia?","COUNT de DOCCAB TIPO=13 por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY D.CODCLIENTE ORDER BY N_FACTURAS DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
