    q("dx_029","Clientes con mayor frecuencia de compra en el trimestre actual","Cuales son los clientes que compran con mas frecuencia en los ultimos 3 meses?","COUNT de DOCCAB TIPO=13 con FECHA>=date('now','-90 days') por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND D.FECHA>=date('now','-90 days') GROUP BY D.CODCLIENTE ORDER BY N_FACTURAS DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_030","Clientes con mayor valor de vida (LTV)","Cuales son los clientes con mayor valor de vida total?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por cliente en toda la historia.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS LTV FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY D.CODCLIENTE ORDER BY LTV DESC LIMIT 20","NULL","Director","KPI","Critico","LTV clientes",""),
    q("dx_031","Clientes con mayor valor de vida en el anio actual","Cuales son los clientes con mayor valor de vida este anio?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 del anio actual por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS LTV_ANIO FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY D.CODCLIENTE ORDER BY LTV_ANIO DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_032","Clientes con mayor valor de vida en el mes actual","Cuales son los clientes con mayor valor de vida este mes?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 del mes actual por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS LTV_MES FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY D.CODCLIENTE ORDER BY LTV_MES DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_033","Clientes con mayor valor de vida en el trimestre actual","Cuales son los clientes con mayor valor de vida en los ultimos 3 meses?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 con FECHA>=date('now','-90 days') por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS LTV_90D FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND D.FECHA>=date('now','-90 days') GROUP BY D.CODCLIENTE ORDER BY LTV_90D DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
