    q("dx_035","Clientes con mayor valor de vida en el ultimo anio","Cuales son los clientes con mayor valor de vida en el ultimo anio?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 con FECHA>=date('now','-365 days') por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS LTV_365D FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND D.FECHA>=date('now','-365 days') GROUP BY D.CODCLIENTE ORDER BY LTV_365D DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_036","Distribucion de clientes por numero de compras","Como se distribuyen los clientes por numero de compras?","COUNT de DOCCAB TIPO=13 por cliente agrupado por rango.","SELECT CASE WHEN N_FACTURAS=1 THEN '1 compra' WHEN N_FACTURAS<=3 THEN '2-3 compras' WHEN N_FACTURAS<=5 THEN '4-5 compras' WHEN N_FACTURAS<=10 THEN '6-10 compras' WHEN N_FACTURAS<=20 THEN '11-20 compras' ELSE '>20 compras' END AS RANGO, COUNT(*) AS N_CLIENTES FROM (SELECT CODCLIENTE, COUNT(*) AS N_FACTURAS FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL GROUP BY CODCLIENTE) GROUP BY RANGO ORDER BY N_CLIENTES DESC","NULL","Director","KPI","Alto","",""),
    q("dx_037","Distribucion de clientes por importe total","Como se distribuyen los clientes por importe total facturado?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por cliente agrupado por rango.","SELECT CASE WHEN TOTAL<100 THEN '<100' WHEN TOTAL<500 THEN '100-500' WHEN TOTAL<1000 THEN '500-1k' WHEN TOTAL<5000 THEN '1k-5k' WHEN TOTAL<10000 THEN '5k-10k' WHEN TOTAL<50000 THEN '10k-50k' ELSE '>50k' END AS RANGO, COUNT(*) AS N_CLIENTES FROM (SELECT CODCLIENTE, SUM(IMPORTETOTAL) AS TOTAL FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL GROUP BY CODCLIENTE) GROUP BY RANGO ORDER BY N_CLIENTES DESC","NULL","Director","KPI","Alto","",""),
    q("dx_038","Distribucion de clientes por provincia","Como se distribuyen los clientes por provincia?","COUNT de CLIENTE por PROVINCIA.","SELECT COALESCE(CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_CLIENTES FROM CLIENTE WHERE BAJA IS NULL OR BAJA!=1 GROUP BY CP ORDER BY N_CLIENTES DESC LIMIT 20","NULL","Director","Geografico","Medio","",""),
    q("dx_039","Distribucion de clientes por codigo postal","Como se distribuyen los clientes por codigo postal?","COUNT de CLIENTE por CP.","SELECT COALESCE(CP,'Sin CP') AS CP, COUNT(*) AS N_CLIENTES FROM CLIENTE WHERE BAJA IS NULL OR BAJA!=1 GROUP BY CP ORDER BY N_CLIENTES DESC LIMIT 20","NULL","Director","Geografico","Medio","",""),
    q("dx_040","Facturacion por provincia","Cuanto se factura en cada provincia?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por provincia del cliente.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY C.CP ORDER BY TOTAL DESC LIMIT 20","NULL","Director","Geografico","Alto","",""),
    q("dx_041","Facturacion por codigo postal","Cuanto se factura en cada codigo postal?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por codigo postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY C.CP ORDER BY TOTAL DESC LIMIT 20","NULL","Director","Geografico","Alto","",""),
    q("dx_042","Facturacion por provincia en el anio actual","Cuanto se factura en cada provincia este anio?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 del anio actual por provincia del cliente.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY C.CP ORDER BY TOTAL DESC LIMIT 20","NULL","Director","Geografico","Alto","",""),
    q("dx_043","Facturacion por provincia en el mes actual","Cuanto se factura en cada provincia este mes?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 del mes actual por provincia del cliente.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY C.CP ORDER BY TOTAL DESC LIMIT 20","NULL","Director","Geografico","Alto","",""),
