    q("dx_046","Facturacion por codigo postal en el anio actual","Cuanto se factura en cada codigo postal este anio?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 del anio actual por codigo postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY C.CP ORDER BY TOTAL DESC LIMIT 20","NULL","Director","Geografico","Alto","",""),
