    q("dx_048","Facturacion por codigo postal en el trimestre actual","Cuanto se factura en cada codigo postal en los ultimos 3 meses?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 con FECHA>=date('now','-90 days') por codigo postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_FACTURAS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 AND D.FECHA>=date('now','-90 days') GROUP BY C.CP ORDER BY TOTAL DESC LIMIT 20","NULL","Director","Geografico","Alto","",""),
