    q("dx_050","Facturacion por agente en el anio actual vs anio anterior","Como compara la facturacion de cada agente este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por agente en el anio actual vs anio anterior.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=strftime('%Y','now') THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB WHERE TIPO=13 AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY ANIO_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Critico","Comparativa agentes",""),
    q("dx_051","Facturacion por agente en el mes actual vs mes anterior","Como compara la facturacion de cada agente este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por agente en el mes actual vs mes anterior.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM DOCCAB WHERE TIPO=13 AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY MES_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Critico","",""),
    q("dx_052","Facturacion por agente en el trimestre actual vs trimestre anterior","Como compara la facturacion de cada agente en el trimestre actual vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por agente en el trimestre actual vs anterior.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, ROUND(SUM(CASE WHEN FECHA>=date('now','-90 days') THEN IMPORTETOTAL ELSE 0 END),2) AS TRIMESTRE_ACTUAL, ROUND(SUM(CASE WHEN FECHA>=date('now','-180 days') AND FECHA<date('now','-90 days') THEN IMPORTETOTAL ELSE 0 END),2) AS TRIMESTRE_ANTERIOR FROM DOCCAB WHERE TIPO=13 AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY TRIMESTRE_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_053","Facturacion por familia en el anio actual vs anio anterior","Como compara la facturacion de cada familia este anio vs el anterior?","SUM(CANTIDAD*PRECIO) de DOCLIN JOIN DOCCAB TIPO=13 por familia en el anio actual vs anio anterior.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=strftime('%Y','now') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=13 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO GROUP BY A.CODFAMILIA ORDER BY ANIO_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_054","Facturacion por familia en el mes actual vs mes anterior","Como compara la facturacion de cada familia este mes vs el anterior?","SUM(CANTIDAD*PRECIO) de DOCLIN JOIN DOCCAB TIPO=13 por familia en el mes actual vs mes anterior.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS MES_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=13 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO GROUP BY A.CODFAMILIA ORDER BY MES_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_055","Facturacion por proveedor en el anio actual vs anio anterior","Como compara la facturacion de cada proveedor este anio vs el anterior?","SUM(CANTIDAD*PRECIO) de DOCLIN JOIN DOCCAB TIPO=13 por proveedor en el anio actual vs anio anterior.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=strftime('%Y','now') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=13 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY ANIO_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_056","Facturacion por cliente en el anio actual vs anio anterior","Como compara la facturacion de cada cliente este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por cliente en el anio actual vs anio anterior.","SELECT "+_C+" AS CLIENTE, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=strftime('%Y','now') THEN D.IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN D.IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY D.CODCLIENTE ORDER BY ANIO_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_057","Facturacion por cliente en el mes actual vs mes anterior","Como compara la facturacion de cada cliente este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por cliente en el mes actual vs mes anterior.","SELECT "+_C+" AS CLIENTE, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') THEN D.IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN D.IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY D.CODCLIENTE ORDER BY MES_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
