    q("dx_062","Facturacion por forma de pago en el anio actual vs anio anterior","Como compara la facturacion de cada forma de pago este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por forma de pago en el anio actual vs anio anterior.","SELECT COALESCE(CODFORMAPAGO,'Sin forma pago') AS FORMA_PAGO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=strftime('%Y','now') THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY CODFORMAPAGO ORDER BY ANIO_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Medio","",""),
    q("dx_063","Facturacion por forma de pago en el mes actual vs mes anterior","Como compara la facturacion de cada forma de pago este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por forma de pago en el mes actual vs mes anterior.","SELECT COALESCE(CODFORMAPAGO,'Sin forma pago') AS FORMA_PAGO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY CODFORMAPAGO ORDER BY MES_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Medio","",""),
    q("dx_064","Facturacion por estado de cobro en el anio actual vs anio anterior","Como compara la facturacion cobrada vs pendiente este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por estado en el anio actual vs anio anterior.","SELECT CASE WHEN ESTADO=1 THEN 'Cobrada' ELSE 'Pendiente' END AS ESTADO_COBRO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=strftime('%Y','now') THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY ESTADO ORDER BY ANIO_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Alto","",""),
    q("dx_065","Facturacion por estado de cobro en el mes actual vs mes anterior","Como compara la facturacion cobrada vs pendiente este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por estado en el mes actual vs mes anterior.","SELECT CASE WHEN ESTADO=1 THEN 'Cobrada' ELSE 'Pendiente' END AS ESTADO_COBRO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY ESTADO ORDER BY MES_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Alto","",""),
    q("dx_066","Facturacion por descuento en el anio actual vs anio anterior","Como compara la facturacion con y sin descuento este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por descuento en el anio actual vs anio anterior.","SELECT CASE WHEN COALESCE(DESCUENTOS,0)>0 THEN 'Con descuento' ELSE 'Sin descuento' END AS TIENE_DESCUENTO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=strftime('%Y','now') THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY TIENE_DESCUENTO ORDER BY ANIO_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Medio","",""),
    q("dx_067","Facturacion por descuento en el mes actual vs mes anterior","Como compara la facturacion con y sin descuento este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por descuento en el mes actual vs mes anterior.","SELECT CASE WHEN COALESCE(DESCUENTOS,0)>0 THEN 'Con descuento' ELSE 'Sin descuento' END AS TIENE_DESCUENTO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY TIENE_DESCUENTO ORDER BY MES_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Medio","",""),
    q("dx_068","Facturacion por rango de importe en el anio actual vs anio anterior","Como compara la distribucion de facturas por importe este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por rango de importe en el anio actual vs anio anterior.","SELECT CASE WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' WHEN IMPORTETOTAL<10000 THEN '5k-10k' ELSE '>10k' END AS RANGO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=strftime('%Y','now') THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY RANGO ORDER BY ANIO_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Medio","",""),
    q("dx_069","Facturacion por rango de importe en el mes actual vs mes anterior","Como compara la distribucion de facturas por importe este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por rango de importe en el mes actual vs mes anterior.","SELECT CASE WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' WHEN IMPORTETOTAL<10000 THEN '5k-10k' ELSE '>10k' END AS RANGO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM DOCCAB WHERE TIPO=13 GROUP BY RANGO ORDER BY MES_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Medio","",""),
    q("dx_070","Facturacion por numero de lineas en el anio actual vs anio anterior","Como compara la distribucion de facturas por numero de lineas este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por rango de lineas en el anio actual vs anio anterior.","SELECT CASE WHEN N_LINEAS=0 THEN 'Sin lineas' WHEN N_LINEAS<=3 THEN '1-3 lineas' WHEN N_LINEAS<=10 THEN '4-10 lineas' ELSE '>10 lineas' END AS RANGO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=strftime('%Y','now') THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM (SELECT D.CODIGO, D.FECHA, D.IMPORTETOTAL, COUNT(L.CODARTICULO) AS N_LINEAS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 GROUP BY D.CODIGO) GROUP BY RANGO ORDER BY ANIO_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Bajo","",""),
    q("dx_071","Facturacion por numero de lineas en el mes actual vs mes anterior","Como compara la distribucion de facturas por numero de lineas este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por rango de lineas en el mes actual vs mes anterior.","SELECT CASE WHEN N_LINEAS=0 THEN 'Sin lineas' WHEN N_LINEAS<=3 THEN '1-3 lineas' WHEN N_LINEAS<=10 THEN '4-10 lineas' ELSE '>10 lineas' END AS RANGO, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM (SELECT D.CODIGO, D.FECHA, D.IMPORTETOTAL, COUNT(L.CODARTICULO) AS N_LINEAS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 GROUP BY D.CODIGO) GROUP BY RANGO ORDER BY MES_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Bajo","",""),
    q("dx_072","Facturacion por dia de la semana en el anio actual vs anio anterior","Como compara la facturacion por dia de la semana este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por dia de la semana en el anio actual vs anio anterior.","SELECT CASE CAST(strftime('%w',FECHA) AS INTEGER) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sabado' END AS DIA, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=strftime('%Y','now') THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB WHERE TIPO=13 AND FECHA IS NOT NULL GROUP BY strftime('%w',FECHA) ORDER BY ANIO_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Bajo","",""),
