    q("dx_079","Facturacion por codigo postal en el anio actual vs anio anterior","Como compara la facturacion de cada codigo postal este anio vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por codigo postal del cliente en el anio actual vs anio anterior.","SELECT COALESCE(C.CP,'Sin CP') AS CP, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=strftime('%Y','now') THEN D.IMPORTETOTAL ELSE 0 END),2) AS ANIO_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN D.IMPORTETOTAL ELSE 0 END),2) AS ANIO_ANTERIOR FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY C.CP ORDER BY ANIO_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Medio","",""),
    q("dx_080","Facturacion por codigo postal en el mes actual vs mes anterior","Como compara la facturacion de cada codigo postal este mes vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por codigo postal del cliente en el mes actual vs mes anterior.","SELECT COALESCE(C.CP,'Sin CP') AS CP, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') THEN D.IMPORTETOTAL ELSE 0 END),2) AS MES_ACTUAL, ROUND(SUM(CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN D.IMPORTETOTAL ELSE 0 END),2) AS MES_ANTERIOR FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=13 GROUP BY C.CP ORDER BY MES_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Medio","",""),
