    q("dx_083","Facturacion por agente en el trimestre actual vs trimestre anterior","Como compara la facturacion de cada agente en el trimestre actual vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por agente en el trimestre actual vs anterior.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, ROUND(SUM(CASE WHEN FECHA>=date('now','-90 days') THEN IMPORTETOTAL ELSE 0 END),2) AS TRIMESTRE_ACTUAL, ROUND(SUM(CASE WHEN FECHA>=date('now','-180 days') AND FECHA<date('now','-90 days') THEN IMPORTETOTAL ELSE 0 END),2) AS TRIMESTRE_ANTERIOR FROM DOCCAB WHERE TIPO=13 AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY TRIMESTRE_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_084","Facturacion por familia en el trimestre actual vs trimestre anterior","Como compara la facturacion de cada familia en el trimestre actual vs el anterior?","SUM(CANTIDAD*PRECIO) de DOCLIN JOIN DOCCAB TIPO=13 por familia en el trimestre actual vs anterior.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, ROUND(SUM(CASE WHEN D.FECHA>=date('now','-90 days') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS TRIMESTRE_ACTUAL, ROUND(SUM(CASE WHEN D.FECHA>=date('now','-180 days') AND D.FECHA<date('now','-90 days') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS TRIMESTRE_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=13 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO GROUP BY A.CODFAMILIA ORDER BY TRIMESTRE_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
    q("dx_085","Facturacion por proveedor en el trimestre actual vs trimestre anterior","Como compara la facturacion de cada proveedor en el trimestre actual vs el anterior?","SUM(CANTIDAD*PRECIO) de DOCLIN JOIN DOCCAB TIPO=13 por proveedor en el trimestre actual vs anterior.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, ROUND(SUM(CASE WHEN D.FECHA>=date('now','-90 days') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS TRIMESTRE_ACTUAL, ROUND(SUM(CASE WHEN D.FECHA>=date('now','-180 days') AND D.FECHA<date('now','-90 days') THEN CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL) ELSE 0 END),2) AS TRIMESTRE_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=13 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY TRIMESTRE_ACTUAL DESC LIMIT 20","NULL","Director","KPI","Alto","",""),
