    q("dx_092","Facturacion por numero de lineas en el trimestre actual vs trimestre anterior","Como compara la distribucion de facturas por numero de lineas en el trimestre actual vs el anterior?","SUM(IMPORTETOTAL) de DOCCAB TIPO=13 por rango de lineas en el trimestre actual vs anterior.","SELECT CASE WHEN N_LINEAS=0 THEN 'Sin lineas' WHEN N_LINEAS<=3 THEN '1-3 lineas' WHEN N_LINEAS<=10 THEN '4-10 lineas' ELSE '>10 lineas' END AS RANGO, ROUND(SUM(CASE WHEN FECHA>=date('now','-90 days') THEN IMPORTETOTAL ELSE 0 END),2) AS TRIMESTRE_ACTUAL, ROUND(SUM(CASE WHEN FECHA>=date('now','-180 days') AND FECHA<date('now','-90 days') THEN IMPORTETOTAL ELSE 0 END),2) AS TRIMESTRE_ANTERIOR FROM (SELECT D.CODIGO, D.FECHA, D.IMPORTETOTAL, COUNT(L.CODARTICULO) AS N_LINEAS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 GROUP BY D.CODIGO) GROUP BY RANGO ORDER BY TRIMESTRE_ACTUAL DESC LIMIT 10","NULL","Director","KPI","Bajo","",""),
